<?php require_once "../config/database.php";require_once "../includes/auth.php";require_role("staff");$s=$conn->prepare("SELECT id FROM staff WHERE user_id=?");$s->bind_param("i",$_SESSION["user_id"]);$s->execute();$sid=$s->get_result()->fetch_assoc()["id"]??0;$s=$conn->prepare("SELECT c.*,u.name student_name FROM complaints c JOIN users u ON c.user_id=u.id WHERE c.assigned_staff_id=? ORDER BY c.created_at DESC");$s->bind_param("i",$sid);$s->execute();$rows=$s->get_result();include "../includes/header.php";?><h2>Staff Dashboard</h2><div class="wrap"><table class="table"><tr><th>ID</th><th>Student</th><th>Title</th><th>Location</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td>SC-<?=str_pad($r["id"],4,"0",STR_PAD_LEFT)?></td><td><?=e($r["student_name"])?></td><td><?=e($r["title"])?></td><td><?=e($r["location"])?></td><td><?=e($r["status"])?></td><td><a href="update_status.php?id=<?=$r["id"]?>">Update</a></td></tr><?php endwhile;?></table></div><?php include "../includes/footer.php";?>